// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }

    function testFuzz_property(uint256 targetBlockNumber, address actor) public {
        vm.assume(actor != address(0));
        uint256 b = bound(targetBlockNumber, block.number, block.number + 1000);

        uint256 callValue = 10 ether;

        vm.deal(actor, callValue);

        vm.roll(b);

        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        (bool ok, ) = address(c).call{value: callValue}("");

        bool notDivBy15 = (b % 15) != 0;
        uint256 bal = address(c).balance;

        assertTrue(!notDivBy15 || bal == callValue);
    }
}
